46	    public static DistributedQueryRunner createRaptorQueryRunner(Map<String, String> extraProperties, boolean loadTpch, boolean bucketed)
47	            throws Exception
48	    {
49	        DistributedQueryRunner queryRunner = new DistributedQueryRunner(createSession("tpch"), 2, extraProperties);
50	
51	        queryRunner.installPlugin(new TpchPlugin());
52	        queryRunner.createCatalog("tpch", "tpch");
53	
54	        queryRunner.installPlugin(new RaptorPlugin());
55	        File baseDir = queryRunner.getCoordinator().getBaseDataDir().toFile();
56	        Map<String, String> raptorProperties = ImmutableMap.<String, String>builder()
57	                .put("metadata.db.type", "h2")
58	                .put("metadata.db.connections.max", "100")
59	                .put("metadata.db.filename", new File(baseDir, "db").getAbsolutePath())
60	                .put("storage.data-directory", new File(baseDir, "data").getAbsolutePath())
61	                .put("storage.max-shard-rows", "2000")
62	                .put("backup.provider", "file")
63	                .put("backup.directory", new File(baseDir, "backup").getAbsolutePath())
64	                .build();
65	
66	        queryRunner.createCatalog("raptor", "raptor", raptorProperties);
67	
68	        if (loadTpch) {
69	            copyTables(queryRunner, "tpch", createSession(), bucketed);
70	        }
71	
72	        return queryRunner;
73	    }
74	
75	    public static void copyTables(QueryRunner queryRunner, String catalog, Session session, boolean bucketed)
76	    {
77	        String schema = TINY_SCHEMA_NAME;
78	        if (!bucketed) {
79	            copyTpchTables(queryRunner, catalog, schema, session, TpchTable.getTables());
80	            return;
81	        }
82	
83	        Map<TpchTable<?>, String> tables = ImmutableMap.<TpchTable<?>, String>builder()
84	                .put(TpchTable.ORDERS, "bucket_count = 25, bucketed_on = ARRAY['orderkey'], distribution_name = 'order'")
85	                .put(TpchTable.LINE_ITEM, "bucket_count = 25, bucketed_on = ARRAY['orderkey'], distribution_name = 'order'")
86	                .put(TpchTable.PART, "bucket_count = 20, bucketed_on = ARRAY['partkey'], distribution_name = 'part'")
87	                .put(TpchTable.PART_SUPPLIER, "bucket_count = 20, bucketed_on = ARRAY['partkey'], distribution_name = 'part'")
88	                .put(TpchTable.SUPPLIER, "bucket_count = 10, bucketed_on = ARRAY['suppkey']")
89	                .put(TpchTable.CUSTOMER, "bucket_count = 10, bucketed_on = ARRAY['custkey']")
90	                .put(TpchTable.NATION, "")
91	                .put(TpchTable.REGION, "")
92	                .build();
93	
94	        log.info("Loading data from %s.%s...", catalog, schema);
95	        long startTime = System.nanoTime();
96	        for (Entry<TpchTable<?>, String> entry : tables.entrySet()) {
97	            copyTable(queryRunner, catalog, session, schema, entry.getKey(), entry.getValue());
98	        }
99	        log.info("Loading from %s.%s complete in %s", catalog, schema, nanosSince(startTime));
100	    }
101	
102	    private static void copyTable(QueryRunner queryRunner, String catalog, Session session, String schema, TpchTable<?> table, String properties)
103	    {
104	        QualifiedObjectName source = new QualifiedObjectName(catalog, schema, table.getTableName());
105	        String target = table.getTableName();
106	
107	        String with = properties.isEmpty() ? "" : format(" WITH (%s)", properties);
108	        @Language("SQL") String sql = format("CREATE TABLE %s%s AS SELECT * FROM %s", target, with, source);
109	
110	        log.info("Running import for %s", target);
111	        long start = System.nanoTime();
112	        long rows = queryRunner.execute(session, sql).getUpdateCount().getAsLong();
113	        log.info("Imported %s rows for %s in %s", rows, target, nanosSince(start));
114	    }
115	
116	    public static Session createSession()
117	    {
118	        return createSession("tpch");
119	    }
120	
121	    public static Session createSession(String schema)
122	    {
123	        SessionPropertyManager sessionPropertyManager = new SessionPropertyManager();
124	        sessionPropertyManager.addConnectorSessionProperties(new ConnectorId("raptor"), new RaptorSessionProperties(new StorageManagerConfig()).getSessionProperties());
125	        return testSessionBuilder(sessionPropertyManager)
126	                .setCatalog("raptor")
127	                .setSchema(schema)
128	                .setSystemProperty("enable_intermediate_aggregations", "true")
129	                .build();
130	    }
131	
132	    public static void main(String[] args)
133	            throws Exception
134	    {
135	        Logging.initialize();
136	        Map<String, String> properties = ImmutableMap.of("http-server.http.port", "8080");
137	        DistributedQueryRunner queryRunner = createRaptorQueryRunner(properties, false, false);
138	        Thread.sleep(10);
139	        Logger log = Logger.get(RaptorQueryRunner.class);
140	        log.info("======== SERVER STARTED ========");
141	        log.info("\n====\n%s\n====", queryRunner.getCoordinator().getBaseUrl());
142	    }
